DROP TABLE IF EXISTS seller_a_shipments;
CREATE TABLE seller_a_shipments (
  shipment_id VARCHAR(12) PRIMARY KEY,
  shop_code VARCHAR(8) NOT NULL,
  buyer_name_raw VARCHAR(80) NOT NULL,
  city_code CHAR(3) NOT NULL,
  ship_date DATE NOT NULL,
  promised_date DATE NOT NULL,
  delivered_date DATE NULL,
  units TINYINT NOT NULL,
  late_fee_per_day DECIMAL(4,2) NOT NULL
);

